<template>
  <div class="menu_box">
    <div class="search">
      <el-button type="primary" size="small" icon="el-icon-plus" @click="openAddDialog">新增菜单</el-button>
    </div>
    <div class="table">
      <div class="jia_table">
        <!-- 菜单数据表格 -->
        <el-table :data="menuList" row-key="menu_id" style="width: 100%" height="95%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }" :tree-props="{children: 'children', hasChildren: 'hasChildren'}">
          <!-- <el-table-column prop="menu_id" label="菜单ID" ></el-table-column> -->
          <el-table-column prop="menu_name" label="菜单名称" ></el-table-column>
          <el-table-column prop="menu_link" label="菜单链接" ></el-table-column>
          <el-table-column prop="menu_order" label="菜单顺序" ></el-table-column>
          <el-table-column prop="menu_status" label="状态" >
            <template slot-scope="scope">
              <el-switch v-model="scope.row.menu_status" active-value="1" inactive-value="2" @change="handleChangeStatus(scope.row)"></el-switch>
            </template>
          </el-table-column>
          <!-- <el-table-column prop="menu_icon" label="图标" ></el-table-column> -->
          <!-- <el-table-column prop="permissions_list" label="权限" ></el-table-column> -->
          <el-table-column label="操作" >
            <template #default="scope">
              <el-button type="text" icon="el-icon-edit" size="small" @click="openEditDialog(scope.row)">编辑</el-button>
              <el-button type="text" icon="el-icon-delete" size="small" @click="deleteMenu(scope.row)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
        <!-- 如果没有数据，显示空状态 -->
        <el-empty v-if="menuList.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
      </div>
      <!-- 分页组件 -->
      <!-- <el-pagination :current-page="currentPage" :page-size="pageSize" :total="menuList.length" layout="total, prev, pager, next, jumper" @current-change="handlePageChange" @size-change="handlePageSizeChange">
      </el-pagination> -->
    </div>
    <!-- 新增/编辑菜单弹框 -->
    <el-dialog :title="isEdit ? '编辑菜单' : '新增菜单'" :visible.sync="dialogVisible" width="600px">
      <el-form :model="form" :rules="rules" ref="form" label-width="100px" class="menuForm" label-position="top">
        <!-- 父菜单ID -->
        <!-- 父菜单ID，树形选择 -->
        <!-- <el-form-item label="父菜单ID">
          <el-tree :data="menuList" :props="treeProps" v-model="form.menu_parent_id" node-key="menu_id" highlight-current :render-content="renderContent" placeholder="请选择父菜单" style="width: 100%;" />
        </el-form-item> -->
        <el-form-item label="父节点" prop="menu_parent_id">
          <treeselect v-model="form.menu_parent_id" :options="menuList" :normalizer="normalizer" placeholder="请选择父节点" />
        </el-form-item>
        <!-- 状态选择：目录/菜单 -->
        <el-form-item label="菜单状态" prop="status">
          <!-- <el-radio v-model="form.status" label="1">目录</el-radio>
          <el-radio v-model="form.status" label="2">菜单</el-radio> -->
          <el-radio-group v-model="form.status">
            <el-radio label="1">目录</el-radio>
            <el-radio label="2">菜单</el-radio>
          </el-radio-group>
        </el-form-item>
        <!-- 菜单名称 -->
        <el-form-item label="菜单名称" prop="menu_name">
          <el-input v-model="form.menu_name" required placeholder="请填入菜单名称"></el-input>
        </el-form-item>

        <!-- 菜单链接 -->
        <el-form-item label="菜单链接" prop="menu_link">
          <el-input v-model="form.menu_link" required placeholder="请填入菜单链接"></el-input>
        </el-form-item>

        <!-- 菜单顺序 -->
        <el-form-item label="菜单顺序" prop="menu_order">
          <el-input v-model="form.menu_order" required placeholder="请填入菜单顺序"></el-input>
        </el-form-item>
        <!-- 是否启用 -->
        <el-form-item label="是否启用" prop="menu_status">
          <el-switch v-model="form.menu_status" active-value="1" inactive-value="2"></el-switch>
        </el-form-item>
      </el-form>

      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="saveMenu">确定</el-button>
      </div>
    </el-dialog>
  </div>
</template>
  
  <script>
import Treeselect from "@riophae/vue-treeselect";
import "@riophae/vue-treeselect/dist/vue-treeselect.css";
import { Message, MessageBox } from 'element-ui'
import { menuApi } from '@/api/system/menu';
export default {
  components: {
    Treeselect
  },
  data() {
    return {
      // 控制弹框显示
      dialogVisible: false,
      isEdit: false,
      form: {
        status: '1',//1目录， 2菜单
        menu_name: '',
        menu_link: '',
        menu_status: '1', // 存储被选中的状态，默认是空数组
        menu_parent_id: '',
        menu_order: '',
        menu_icon: '',
      },
      rules: {
        status: [{ required: true, message: '请选择状态', trigger: 'change' }],
        menu_name: [{ required: true, message: '请输入菜单名称', trigger: 'blur' }],
        menu_link: [{ required: false, message: '请输入菜单链接', trigger: 'blur' }],
        menu_order: [{
          validator: (rule, value, callback) => {
            if (!/^\d+$/.test(value)) {
              callback(new Error('菜单顺序必须为数字'));
            } else {
              callback();
            }
          }, trigger: 'blur'
        }],
      },
      // 菜单数据
      menuList: [],
      treeProps: { label: 'menu_name', children: 'children' },
    };
  },
  created() {
    this.getMenuList();
  },
  mounted() { },
  methods: {
    /** 转换tree数据结构 */
    normalizer(node) {
      if (node.children && !node.children.length) {
        delete node.children;
      }
      return {
        id: node.menu_id,
        label: node.menu_name,
        children: node.children
      };
    },
    // 获取菜单数据
    getMenuList() {
      this.$http.get(menuApi.getMenuList).then(res => {
        this.menuList = res.data.data.menu_list;
      })
    },
    // 打开新增菜单弹框
    openAddDialog() {
      this.isEdit = false;
      this.form = { menu_id: '', menu_name: '', menu_link: '', menu_icon: '', permissions_list: [] };
      this.dialogVisible = true;
    },

    // 打开编辑菜单弹框
    openEditDialog(menu) {
      let status = '';
      if (menu.menu_parent_id == null) {
        status = '1';
      } else {
        status = '2';
      }
      this.isEdit = true;
      this.form = { ...menu, status: status };
      this.dialogVisible = true;
    },

    // 保存新增或修改菜单
    saveMenu() {
      // console.log(this.form)
      this.$refs.form.validate(valid => {
        if (valid) {
          if (this.form.status == 1) {
            this.form.menu_parent_id = null;
          } else {
            // 判断是否选择了父节点
            if (!this.form.menu_parent_id) {
              this.$message({ type: 'warning', message: '请选择父节点' });
              return;
            }
          }
          let formData = new FormData();
          // 遍历 form 对象，并将键值对添加到 formData 中
          Object.keys(this.form).forEach(key => {
            formData.append(key, this.form[key]);
          });
          let config = {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          };
          this.$http.post(this.isEdit ? menuApi.editMenu : menuApi.addMenu, formData, config).then(res => {
            if (res.data.code == 200) {
              this.$message({ type: 'success', message: res.data.msg });
              this.getMenuList();
              this.dialogVisible = false;
            } else {
              this.$message({ type: 'warning', message: res.data.msg });
            }
          }).catch(err => {
            console.log(err);
          })
        }
      })
    },

    // 保存菜单状态
    saveMenuStatus() {
      // console.log(this.form)
      if (this.isEdit) {

      } else {

      }
      // this.dialogVisible = false;
    },

    // 删除菜单
    deleteMenu(menu) {
      this.$confirm('是否确定删除该菜单?', '提示', { type: 'warning' }).then(() => {
        let arr = [];
        if (Array.isArray(menu.children) && menu.children.length > 0) {
          arr = menu.children.map(v => v.menu_id);
        }
        let data = { menu_list: JSON.stringify([menu.menu_id, ...arr]) };
        console.log(data)
        let formData = new FormData();
        // 遍历 msg 对象，并将键值对添加到 formData 中
        Object.keys(data).forEach(key => {
          formData.append(key, data[key]);
        });
        let config = {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        };
        this.$http.post(menuApi.deleteMenu, data, config).then(res => {
          if (res.data.code == 200) {
            this.$message({ type: 'success', message: res.data.message });
            this.getMenuList();
          } else {
            this.$message({ type: 'warning', message: res.data.message });
          }
        }).catch(err => {
          console.log(err);
        })
      }).catch(() => {
        Message.info('已取消删除');
      });
    },
    // 修改菜单状态
    handleChangeStatus(menu) {
      this.$confirm('是否确定修改该菜单状态?', '提示', { type: 'warning' }).then(() => {
        let data = { menu_id: menu.menu_id, menu_status: menu.menu_status };
        let formData = new FormData();
        // 遍历 msg 对象，并将键值对添加到 formData 中
        Object.keys(data).forEach(key => {
          formData.append(key, data[key]);
        });
        let config = {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        };
        this.$http.post(menuApi.changeMenuStatus, data, config).then(res => {
          if (res.data.code == 200) {
            this.$message({ type: 'success', message: res.data.message });
            this.getMenuList();
          } else {
            this.$message({ type: 'warning', message: res.data.message });
          }
        }).catch(err => {
          console.log(err);
        })
      }).catch(() => {
        Message.info('已取消删除');
        this.getMenuList();
      });
    }

  },
};
  </script>
  
  <style  lang="scss" scoped>
.menu_box {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 6px;
  .search {
    height: 70px;
    // padding-top: 16px;
    // padding-bottom: 16px;
    padding: 16px 18px;
    box-sizing: border-box;
    position: relative;
    .demo-ruleForm {
      height: 100%;
      display: flex;
      justify-content: left;
      align-items: flex-start;
      flex-wrap: wrap;
    }
  }
  .table {
    height: 87%;
    position: relative;
    .jia_table {
      height: 100%;
      .el-table {
        height: 100%;
        background-image: url("../../img/home/placeholder_bottom.png");
  background-position: bottom;
  background-size: 100% 60%;
  background-repeat: no-repeat;
      }
      ::v-deep .el-table--border .el-table__cell,
      .el-table__body-wrapper .el-table--border.is-scrolling-left ~ .el-table__fixed {
        border-right: none;
      }
      ::v-deep .el-table__empty-block {
        // display: none !important;
        .el-table__empty-text {
          color: transparent;
        }
      }
      ::v-deep .el-empty {
        width: 307px;
        height: 353px;
        position: absolute;
        top: 50%;
        left: 50%;
        margin-left: -153px;
        margin-top: -176px;
        .el-empty__image img {
          vertical-align: top;
          height: 147%;
          width: 100%;
        }
        .el-empty__description {
          margin-top: 20px;
          margin-right: 70px;
        }
      }
    }
    .page {
      width: 100%;
      height: 33px;
      // background-color: pink;
      text-align: right;
      position: absolute;
      right: 0;
      bottom: -24px;
    }
  }
  ::v-deep .menuForm {
    .el-form-item {
      margin-bottom: 0 !important;
    }
    .el-form-item__label {
      padding-bottom: 0;
    }
    .el-select,
    .el-input {
      // width: 177px;
      .el-input__inner {
        // width: 177px;
        // height: 33px;
        background: #f7f6fb;
        border-radius: 4px;
        border: 1px solid #dcdfe6;
        box-sizing: border-box;
      }
      .el-input__suffix-inner {
        border-left: 1px solid #dcdfe6;
      }
    }
  }
}
</style>